(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const btns = Array.from(document.querySelectorAll('button')).filter(b => /Confirm\s*OTP/i.test((b.innerText||'').replace(/\s+/g,' ')));
  let hit = 0;
  for (const b of btns) { try { b.click(); hit++; } catch(e) {} }
  await sleep(10000);
  return JSON.stringify({hit, url: location.href,
    toasts: Array.from(document.querySelectorAll('div')).map(e=>(e.innerText||'').replace(/\s+/g,' ').trim()).filter(t=>/wrong|incorrect|invalid|expired|error|try|sent|login/i.test(t) && t.length<110).filter((v,i,a)=>a.indexOf(v)===i).slice(0,6),
    inputs: Array.from(document.querySelectorAll('input')).filter(i=>i.offsetParent!==null).map(i=>i.id).slice(0,8)
  });
})()
